void abort(void);
void exit(int);

struct s {
  int f[4];
};

int foo(struct s s, int x1, int x2, int x3, int x4, int x5, int x6, int x7) {
  return s.f[3] + x7;
}

int main() {
  struct s s = {1, 2, 3, 4};

  if (foo(s, 100, 200, 300, 400, 500, 600, 700) != 704)
    abort();
  exit(0);
}


